#!/usr/bin/env bash
# Research OS bootstrap for Etude. Generated by:
#   uv run python -m etude.evolution.research_bridge --bootstrap-script > scripts/research_bootstrap.sh
# One-time sequence (docs/research_os_usage.md §1):
#   1) research init (human statement)
#   2) H-1/H-2/H-3 = 条件 2/3/4
#   3) 7 committed Experiments, each followed by its contract-authority request
#   4) The user grants each contract (printed at the end; it cannot be scripted ahead)
# Agents must never fill RESEARCH_HUMAN / RESEARCH_QUOTE / RESEARCH_CHANNEL. The user sets them, using their own words.
# Usage:
#   RESEARCH_HUMAN=<id> RESEARCH_QUOTE='<你的原话>' RESEARCH_CHANNEL=<渠道> RESEARCH_GOAL='<目标>' \
#   RESEARCH_ACTOR=agent:<id> bash scripts/research_bootstrap.sh
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"
: "${RESEARCH_HUMAN:?set RESEARCH_HUMAN to your id}"
: "${RESEARCH_QUOTE:?set RESEARCH_QUOTE to your verbatim words}"
: "${RESEARCH_CHANNEL:?set RESEARCH_CHANNEL, e.g. claude-code}"
: "${RESEARCH_GOAL:?set RESEARCH_GOAL}"
: "${RESEARCH_ACTOR:?set RESEARCH_ACTOR=agent:<id>}"
test ! -f research/ledger.json || { echo "research/ledger.json already exists; bootstrap is one-time" >&2; exit 1; }
R="uv run python research/tools/research"

# 0) every view file exists and passes the ViewSpec schema + R44 rules
uv run python -m etude.evolution.research_bridge --check-views

# 1) init: human statement (research/AGENTS.md 科学记录与授权)
$R init \
  --human "${RESEARCH_HUMAN}" \
  --quote "${RESEARCH_QUOTE}" \
  --channel "${RESEARCH_CHANNEL}" \
  --goal "${RESEARCH_GOAL}" \
  --metric success_rate \
  --baseline 'π0.5 每 N 步重查的最佳 N' \
  --constraint 'π0.5 权重冻结；只演化 evolvable/ 白名单三文件' \
  --constraint '禁读清单由 frozen/forbidden.yaml 与 AST 检查强制' \
  --constraint 'V/T 结果对编辑者不可读；T 只看一次' \
  --constraint 'Run 只执行已 commit 且已推送 origin 的源码'

# 2) hypotheses, in this order so the aliases come out as H-1/H-2/H-3
$R hypothesis \
  create \
  --statement '条件 2：冻结 π0.5 加节点执行器、代码验证器与节点边界规划（harness H1，记忆关），在开发任务 seed 0/1 同布局配对上，成功率比 π0.5 每 N 步重查的最佳 N（M0 的 N*）高至少 ε 且 McNemar p≤0.05，漏检率不升' \
  --scope condition=2 \
  --scope task=stack_bowls,put_bottles_into_dustbin,build_tower,make_kong
$R hypothesis \
  create \
  --statement '条件 3：在 H1 上加只读节点序列记忆（E 划分积累，入库 = 官方成功 ∧ 全节点 Pass，目标只存 perceive 查询），seed 1 成功率比条件 2 高至少 ε，打乱记忆对照不超过 SR1 + δ，且在 seed 2 上不缩水超过 δ_AA' \
  --scope condition=3 \
  --scope task=stack_bowls,put_bottles_into_dustbin
$R hypothesis \
  create \
  --statement '条件 4：harness 回路逐面进化（规划 prompt → 恢复规则 → SKILL.md，每候选过 L0–L3 门）得到的 H*，在 T（开发任务 seed 2 + 留出任务 seed 0/1/2）上配对成功率比冻结 H2 高至少 ε，且不低于同预算扩记忆的 M2+ 减 ε' \
  --scope condition=4 \
  --scope task=stack_bowls,put_bottles_into_dustbin,build_tower,make_kong \
  --scope surface=planner_prompt,recovery_rules,skill_md

# 3) committed experiments, in this order so the aliases come out as E-M0→E-1, E-M0-AA→E-2, E-M1→E-3, E-M1-AA→E-4, E-M2→E-5, E-M3→E-6, E-M3-T→E-7
# E-M0
$R experiment \
  create \
  --hypothesis H-1 \
  --mode committed \
  --kind search \
  --intent '冻结 π0.5 官方流程下，每块执行前 N∈{5,10,15,25,50} 步对 SR 的影响；选 N*；记 t_step 与 A/A 的 δ；量验证器对官方 judge 的 FPR/FNR' \
  --decision-rule '§5 M0 预注册通过：跑完、t_step 与 A/A 的 δ 记下；FPR ≤5%（否则验证器先修）。' \
  --baseline 'π0.5 joint-0/59999 官方流程（N=50 行，对照官方榜 11.44）' \
  --metric success_rate \
  --view experiments/M0/view.json
$R authority \
  request \
  E-1 \
  --scope experiment_contract \
  --diff '新建 committed 契约 E-M0：冻结 π0.5 官方流程下，每块执行前 N∈{5,10,15,25,50} 步对 SR 的影响；选 N*；记 t_step 与 A/A 的 δ；量验证器对官方 ' \
  --on-approve 'E-1 可以开始 research run' \
  --would-change '否：契约在任何 Run 之前登记'

# E-M0-AA
$R experiment \
  create \
  --hypothesis H-1 \
  --mode committed \
  --kind replication \
  --intent '现任 π0.5@N* 在 V（seed 1，开发任务 100 回合）上重跑 3 次，得 δ_AA 与 ε' \
  --decision-rule '§3.2 A/A：现任 harness 在 V 上重跑 3 次。§3.3 ε 校准：eps = max(4, max(abs(a - b) for a, b in pairs(S)) + 1)（COAP 2610.12369 App. B 的 4 是下限）。§5 M3 卡点：A/A 给出的 ε 不能大于 15，否则 V 扩到 150。' \
  --baseline 'π0.5@N* 自身（A/A）' \
  --metric success_rate \
  --view experiments/M0/view_aa.json
$R authority \
  request \
  E-2 \
  --scope experiment_contract \
  --diff '新建 committed 契约 E-M0-AA：现任 π0.5@N* 在 V（seed 1，开发任务 100 回合）上重跑 3 次，得 δ_AA 与 ε' \
  --on-approve 'E-2 可以开始 research run' \
  --would-change '否：契约在任何 Run 之前登记'

# E-M1
$R experiment \
  create \
  --hypothesis H-1 \
  --mode committed \
  --kind main \
  --intent '完整 harness H1（记忆关、VLA exec_steps=N*）相对 M0(N*) 的配对 SR 增益' \
  --decision-rule '§5 M1 预注册通过：配对 SR1 − SR0(N*) ≥ ε 且 p≤0.05（开发任务 seed 0/1 合并 200 回合）；FNR 不升。§6 证伪「条件 2 不超过最好的 N」：统计量 同布局配对 McNemar，开发任务 seed 0/1（200 回合）；余量 b−c < ε 或 p>0.05；或漏检率上升 >2 pp；后果 如实写成"带验证器的定时重查器"；M2 仍做（记忆对重查器也可测），M3 只开恢复规则一个面。§6 证伪「收益全来自缩短重查步长」：统计量 M1 内 VLA 节点 `exec_steps` 固定为 N*；对照 M0(N*)；Long-WAM 2610.10528 §6：原子任务 15 步重查 84.4 ≈ 层级 85.6，复合任务 11.2/5.0 对 38.8/35.0；余量 若 put_bottles/make_kong 上 M1 − M0(N*) < ε 而 stack_bowls 上 ≥ε；后果 结论限定为"短程任务收益=重查"。' \
  --baseline 'M0 cell n=N*（同任务同 seed 同布局）' \
  --metric success_rate \
  --view experiments/M1/view.json
$R authority \
  request \
  E-3 \
  --scope experiment_contract \
  --diff '新建 committed 契约 E-M1：完整 harness H1（记忆关、VLA exec_steps=N*）相对 M0(N*) 的配对 SR 增益' \
  --on-approve 'E-3 可以开始 research run' \
  --would-change '否：契约在任何 Run 之前登记'

# E-M1-AA
$R experiment \
  create \
  --hypothesis H-1 \
  --mode committed \
  --kind replication \
  --intent '现任 H1 在 V 上重跑 3 次，得 M1 的 δ_AA 与 ε' \
  --decision-rule '§3.2 A/A：现任 harness 在 V 上重跑 3 次。§3.3 ε 校准：eps = max(4, max(abs(a - b) for a, b in pairs(S)) + 1)（COAP 2610.12369 App. B 的 4 是下限）。§5 M3 卡点：A/A 给出的 ε 不能大于 15，否则 V 扩到 150。' \
  --baseline 'H1 自身（A/A）' \
  --metric success_rate \
  --view experiments/M1/view_aa.json
$R authority \
  request \
  E-4 \
  --scope experiment_contract \
  --diff '新建 committed 契约 E-M1-AA：现任 H1 在 V 上重跑 3 次，得 M1 的 δ_AA 与 ε' \
  --on-approve 'E-4 可以开始 research run' \
  --would-change '否：契约在任何 Run 之前登记'

# E-M2
$R experiment \
  create \
  --hypothesis H-2 \
  --mode committed \
  --kind main \
  --intent '记忆回路（E 上积累的节点序列库，评测期冻结）相对 H1 的增益，及打乱记忆对照' \
  --decision-rule '§5 M2 预注册通过：SR2(seed1) − SR1(seed1) ≥ ε；打乱记忆 ≤ SR1 + δ。§6 证伪「条件 3 在留出上缩水」：统计量 开发任务 seed 2：SR2 − SR1；余量 < −δ_AA；后果 序列泄漏布局信息，回查 schema。' \
  --baseline 'M1 cell condition=h1（同任务同 seed 同布局）' \
  --metric success_rate \
  --view experiments/M2/view.json
$R authority \
  request \
  E-5 \
  --scope experiment_contract \
  --diff '新建 committed 契约 E-M2：记忆回路（E 上积累的节点序列库，评测期冻结）相对 H1 的增益，及打乱记忆对照' \
  --on-approve 'E-5 可以开始 research run' \
  --would-change '否：契约在任何 Run 之前登记'

# E-M3
$R experiment \
  create \
  --hypothesis H-3 \
  --mode committed \
  --kind search \
  --intent 'harness 回路按 规划 prompt → 恢复规则 → SKILL.md 逐面进化，每面 R≤4 轮，过 L0–L3 门' \
  --decision-rule '§5 M3 预注册通过：每面至少 1 次 accept；T 上 H* − H2 ≥ ε（seed 2 + 留出）。§3.1 门：L0 静态 → L1 medoid 重跑（≤5 回合，Zetta 2608.16590 §2.5.2）→ L2 历史回归集 F（≤20 回合，≤1 次失守）→ L3 配对留出（V=100 回合，b−c≥ε 且 McNemar p≤0.05）→ 成本 ΔC≤β0+β1·ΔSR（RRSI §3.3）。§5 M3 卡点：A/A 给出的 ε 不能大于 15，否则 V 扩到 150。§6 证伪「停止规则」：统计量 连续 3 轮 reject；或 V 已被 6 个候选复用；或预算用尽；或 ε>15；余量 —；后果 冻结现任，进入 T。' \
  --baseline '冻结 H2（M2 现任）' \
  --metric success_rate \
  --view experiments/M3/view.json
$R authority \
  request \
  E-6 \
  --scope experiment_contract \
  --diff '新建 committed 契约 E-M3：harness 回路按 规划 prompt → 恢复规则 → SKILL.md 逐面进化，每面 R≤4 轮，过 L0–L3 门' \
  --on-approve 'E-6 可以开始 research run' \
  --would-change '否：契约在任何 Run 之前登记'

# E-M3-T
$R experiment \
  create \
  --hypothesis H-3 \
  --mode committed \
  --kind main \
  --intent '最终一次 T：H* 对冻结 H2，开发任务 seed 2 + 留出任务 seed 0/1/2' \
  --decision-rule '§5 M3 预注册通过：每面至少 1 次 accept；T 上 H* − H2 ≥ ε（seed 2 + 留出）。§6 证伪「进化后 seed 2 不超过冻结 harness」：统计量 T 上 H* − H2 配对；余量 < ε；后果 记 M3 证伪，保留 H2。§6 证伪「同回合同 VLM 预算 M3 ≤ M2」：统计量 M2+ = M2 用同等额外回合扩记忆；比较 H* 与 M2+；余量 H* − M2+ < ε；后果 进化不值。' \
  --baseline '冻结 H2' \
  --metric success_rate \
  --view experiments/M3/view_T.json
$R authority \
  request \
  E-7 \
  --scope experiment_contract \
  --diff '新建 committed 契约 E-M3-T：最终一次 T：H* 对冻结 H2，开发任务 seed 2 + 留出任务 seed 0/1/2' \
  --on-approve 'E-7 可以开始 research run' \
  --would-change '否：契约在任何 Run 之前登记'

# 4) The user grants each contract (agents never run this). List the open requests:
$R pending-authority
cat <<'EOF'
For each request event_id above, grant it yourself, quoting your own words:
  RESEARCH_ACTOR=agent:<id> uv run python research/tools/research authority grant <REQUEST_EVENT_ID> \
    --human <你的id> --quote "<你的原话>" --channel <渠道>
Then commit the ledger: git add research/ledger.json && git commit -m 'research: bootstrap ledger' && git push origin main
EOF
